package com.daybreak.clock;

import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import org.json.*;
import java.io.*;
import java.net.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;

final class AppUpdater {
    private final MainActivity activity;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final Handler handler=new Handler(Looper.getMainLooper());
    private final File apk;
    private UpdateManifest available;
    private JSONObject state=new JSONObject();
    private boolean busy=false,closed=false;
    AppUpdater(MainActivity a){activity=a;apk=new File(a.getCacheDir(),"daybreak-update.apk");setState("idle","Check for a newer Daybreak version.",0);}
    private long installed(){try{return activity.getPackageManager().getPackageInfo(activity.getPackageName(),0).getLongVersionCode();}catch(PackageManager.NameNotFoundException e){return 0;}}
    synchronized String state(){try{state.put("installedVersion",activity.getPackageManager().getPackageInfo(activity.getPackageName(),0).versionName);state.put("installedCode",installed());if(available!=null){state.put("versionName",available.versionName);state.put("notes",available.notes);}return state.toString();}catch(Exception e){return "{}";}}
    private synchronized void setState(String phase,String message,int progress){try{state=new JSONObject().put("phase",phase).put("message",message).put("progress",progress);}catch(JSONException ignored){}handler.post(()->{if(!closed)activity.js("window.onNativeUpdate&&onNativeUpdate("+state()+")");});}
    private HttpURLConnection connect(String address)throws Exception{for(int i=0;i<6;i++){if(!UpdateManifest.trustedDownload(address))throw new IOException("The update download address is not trusted.");HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestProperty("User-Agent","Daybreak Android updater");c.setRequestProperty("Cache-Control","no-cache");int code=c.getResponseCode();if(code>=300&&code<400){String location=c.getHeaderField("Location");String next=new URL(new URL(address),location).toString();c.disconnect();address=next;continue;}if(code==404){c.disconnect();throw new FileNotFoundException("The Daybreak update channel has not been published yet.");}if(code!=200){c.disconnect();throw new IOException("The update server is unavailable. Try again later.");}return c;}throw new IOException("Too many download redirects.");}
    void check(){synchronized(this){if(busy)return;busy=true;}setState("checking","Checking the Daybreak GitHub update channel…",0);worker.execute(()->{try{HttpURLConnection c=connect(UpdateManifest.MANIFEST_URL+"?check="+System.currentTimeMillis());String json;try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>65536)throw new IOException("Update information is too large.");out.write(b,0,n);}json=new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8);}finally{c.disconnect();}JSONObject channel=new JSONObject(json);if(!channel.optBoolean("enabled",true)){available=null;setState("paused","Updates are paused pending a security review. No update will be downloaded.",0);return;}UpdateManifest next=new UpdateManifest(json);if(next.minSdk>Build.VERSION.SDK_INT){available=null;setState("unavailable","This update requires a newer Android version.",0);}else if(next.versionCode<=installed()){available=null;setState("current","Daybreak is up to date.",0);}else{available=next;setState("available","A newer Daybreak version is available.",0);}AlarmStore.prefs(activity).edit().putLong("lastUpdateCheck",System.currentTimeMillis()).apply();}catch(Exception e){setState("error",e instanceof FileNotFoundException?e.getMessage():"Could not check for updates. Check your internet connection and try again.",0);}finally{synchronized(this){busy=false;}}});}
    void download(){UpdateManifest chosen=available;synchronized(this){if(busy||chosen==null)return;busy=true;}setState("downloading","Downloading the update…",0);worker.execute(()->{try{HttpURLConnection c=connect(chosen.apkUrl);MessageDigest digest=MessageDigest.getInstance("SHA-256");long total=0;try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(apk)){byte[] buffer=new byte[65536];int n;int last=-1;while((n=in.read(buffer))!=-1){if(Thread.currentThread().isInterrupted()||closed)throw new IOException("Download cancelled.");total+=n;if(total>chosen.size||total>UpdateManifest.MAX_BYTES)throw new IOException("The update size does not match.");out.write(buffer,0,n);digest.update(buffer,0,n);int progress=(int)(100*total/chosen.size);if(progress/5!=last){last=progress/5;setState("downloading","Downloading the update…",progress);}}}finally{c.disconnect();}if(total!=chosen.size||!hex(digest.digest()).equals(chosen.sha256))throw new IOException("The downloaded update failed its integrity check.");verifyPackage(chosen);setState("ready","Update verified. Tap Install update, then confirm with Android.",100);handler.postDelayed(()->{if(!closed&&activity.visible)install();},200);}catch(Exception e){apk.delete();setState("error",e instanceof IOException?e.getMessage():"The update could not be verified. Nothing was installed.",0);}finally{synchronized(this){busy=false;}}});}
    private static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
    private static Set<String> signers(PackageInfo p)throws Exception{if(p.signingInfo==null)throw new IOException("The update has no signing certificate.");Set<String> result=new HashSet<>();for(Signature s:p.signingInfo.getApkContentsSigners())result.add(hex(MessageDigest.getInstance("SHA-256").digest(s.toByteArray())));return result;}
    private void verifyPackage(UpdateManifest release)throws Exception{PackageManager pm=activity.getPackageManager();PackageInfo candidate=pm.getPackageArchiveInfo(apk.getAbsolutePath(),PackageManager.GET_SIGNING_CERTIFICATES),current=pm.getPackageInfo(activity.getPackageName(),PackageManager.GET_SIGNING_CERTIFICATES);if(candidate==null||!activity.getPackageName().equals(candidate.packageName)||candidate.getLongVersionCode()!=release.versionCode||candidate.getLongVersionCode()<=current.getLongVersionCode())throw new IOException("The APK does not match this Daybreak update.");if(!signers(candidate).equals(signers(current)))throw new IOException("The update was signed by a different developer. Nothing was installed.");}
    private boolean safeToInstall(){if(AlarmService.active(activity))return false;long now=System.currentTimeMillis();org.json.JSONArray alarms=AlarmStore.alarms(activity);for(int i=0;i<alarms.length();i++){JSONObject a=alarms.optJSONObject(i);if(a!=null&&a.optBoolean("enabled")){long next=AlarmStore.next(a,now);if(next>now&&next-now<300000)return false;}}return true;}
    void install(){if(available==null||!apk.isFile())return;if(!safeToInstall()){setState("ready","Wait until the ringing alarm or an alarm due within five minutes is finished before installing.",100);return;}if(!activity.getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(activity).setTitle("Allow Daybreak updates").setMessage("Android needs your approval for Daybreak to install its updates. Enable this source, return here, then tap Install update again.").setPositiveButton("Open Android settings",(d,w)->activity.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())))).setNegativeButton("Not now",null).show();return;}synchronized(this){if(busy)return;busy=true;}setState("installing","Preparing Android’s update confirmation…",100);worker.execute(()->{int sessionId=-1;try{verifyPackage(available);if(!safeToInstall())throw new IOException("An alarm is due. Install the update after it finishes.");PackageInstaller installer=activity.getPackageManager().getPackageInstaller();PackageInstaller.SessionParams params=new PackageInstaller.SessionParams(PackageInstaller.SessionParams.MODE_FULL_INSTALL);params.setAppPackageName(activity.getPackageName());params.setSize(apk.length());params.setInstallReason(PackageManager.INSTALL_REASON_USER);if(Build.VERSION.SDK_INT>=31)params.setRequireUserAction(PackageInstaller.SessionParams.USER_ACTION_REQUIRED);if(Build.VERSION.SDK_INT>=33)params.setPackageSource(PackageInstaller.PACKAGE_SOURCE_DOWNLOADED_FILE);sessionId=installer.createSession(params);try(PackageInstaller.Session session=installer.openSession(sessionId)){try(InputStream in=new FileInputStream(apk);OutputStream out=session.openWrite("base.apk",0,apk.length())){byte[] chunk=new byte[65536];int read;while((read=in.read(chunk))!=-1)out.write(chunk,0,read);session.fsync(out);}Intent result=new Intent(activity,UpdateInstallActivity.class);ActivityOptions options=null;if(Build.VERSION.SDK_INT>=34)options=ActivityOptions.makeBasic().setPendingIntentCreatorBackgroundActivityStartMode(ActivityOptions.MODE_BACKGROUND_ACTIVITY_START_ALLOWED);PendingIntent callback=PendingIntent.getActivity(activity,sessionId,result,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE,options==null?null:options.toBundle());session.commit(callback.getIntentSender());}}catch(Exception e){if(sessionId!=-1)try{activity.getPackageManager().getPackageInstaller().abandonSession(sessionId);}catch(RuntimeException ignored){}setState("ready",e instanceof IOException?e.getMessage():"Could not open Android’s installer. Try again.",100);}finally{synchronized(this){busy=false;}}});}
    void onResume(){String result=AlarmStore.prefs(activity).getString("updateResult",null);if(result!=null){AlarmStore.prefs(activity).edit().remove("updateResult").apply();setState(available!=null&&apk.isFile()?"ready":"idle",result,0);}}
    void close(){closed=true;handler.removeCallbacksAndMessages(null);worker.shutdownNow();}
}


